package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DateTimeException;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadLoanPort loadLoanPort;

    public GetMonthlyStatsService(LoadLoanPort loadLoanPort) {
        this.loadLoanPort = loadLoanPort;
    }

    /** 대출 건수는 대출일, 반납·연체 건수와 연체료 합계는 반납일 기준으로 센다. */
    @Override
    public MonthlyStats getMonthlyStats(int year, int month) {
        YearMonth yearMonth = toYearMonth(year, month);
        LocalDate from = yearMonth.atDay(1);
        LocalDate to = yearMonth.plusMonths(1).atDay(1);

        long loanCount = loadLoanPort.loadLoansLoanedBetween(from, to).size();
        List<Loan> returned = loadLoanPort.loadLoansReturnedBetween(from, to);
        long overdueCount = returned.stream().filter(loan -> loan.lateFee() > 0).count();
        long lateFeeTotal = returned.stream().mapToLong(Loan::lateFee).sum();

        return new MonthlyStats(year, month, loanCount, returned.size(), overdueCount, lateFeeTotal);
    }

    private YearMonth toYearMonth(int year, int month) {
        try {
            return YearMonth.of(year, month);
        } catch (DateTimeException e) {
            throw new IllegalArgumentException(e.getMessage(), e);
        }
    }
}
