import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class StatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void monthly_stats_count_loans_by_loan_date_and_returns_by_return_date() throws Exception {
        String memberA = registerMember();
        String memberB = registerMember();

        // 4월 대출, 5월에 기한 내 반납 → 5월 반납 1건, 연체 없음
        String aprilLoan = loan(registerBook("April Book"), memberA, "2041-04-20");
        // 5월 대출, 미반납 → 5월 대출 건수에만 포함
        loan(registerBook("Active Book"), memberA, "2041-05-02");
        // 5월 대출, 6일 연체 반납 → 600
        String lateLoan = loan(registerBook("Late Book"), memberB, "2041-05-10");
        // 5월 대출, 5일 연체 반납 → 500
        String lateLoan2 = loan(registerBook("Late Book 2"), memberB, "2041-05-01");

        returnLoan(aprilLoan, "2041-05-03");
        returnLoan(lateLoan, "2041-05-30");
        returnLoan(lateLoan2, "2041-05-20");

        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "5"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2041))
                .andExpect(jsonPath("$.month").value(5))
                .andExpect(jsonPath("$.loanCount").value(3))
                .andExpect(jsonPath("$.returnCount").value(3))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(1100));

        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "4"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(1))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void month_without_activity_returns_zeros() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "12"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void invalid_month_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "13"))
                .andExpect(status().isBadRequest());
    }

    private void returnLoan(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String loan(String bookId, String memberId, String loanedAt) throws Exception {
        String body = "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}";
        String created = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(created).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"이서준\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }
}
